pub fn retry(
    transient: bool,
    failed_attempts: u32,
    maximum: u32,
    delay: u64,
    operation_budget: u64,
    remaining: u64,
) -> bool {
    transient
        && failed_attempts > 0
        && failed_attempts < maximum
        && delay
            .checked_add(operation_budget)
            .is_some_and(|cost| cost <= remaining)
}

fn main() {
    assert_eq!(retry(true, 1, 3, 10, 20, 30), true, "case 1");
    assert_eq!(retry(true, 0, 3, 0, 0, 0), false, "case 2");
    assert_eq!(retry(false, 1, 3, 0, 0, 100), false, "case 3");
    assert_eq!(retry(true, 3, 3, 0, 0, 100), false, "case 4");
    assert_eq!(
        retry(true, 1, 3, u64::MAX, 1, u64::MAX),
        false,
        "case 5"
    );
    assert_eq!(retry(true, 1, 3, 10, 20, 29), false, "case 6");
    println!("worked example passed");
}

